require(['jquery', 'xwiki-meta', 'xwiki-ckeditor', 'jquery-ui'], function ($, xm, ckePromise) {
  class GuidedTourStepSheetManager {
    stepElements = {};
    // List of initial steps on the page, so we can compute a diff when the user saves.
    initialStepObjects = [];
    // FIXME: Test what happens if I have steps [1,2,3], delete 2, and add a new step. New step == 2 or == 4 ?
    registerStep(objectIndex, form, sidebarItem) {
      this.stepElements[objectIndex] = {
        number: objectIndex,
        form: form,
        sidebarItem: sidebarItem,
      }
      if (!this.formContainer.contains(form)) {
        this.formContainer.appendChild(form);
      }
      if (!this.sidebarContainer.contains(sidebarItem)) {
        this.sidebarContainer.appendChild(sidebarItem);
      }
    }
    constructor(formContainer, sidebarContainer) {
      this.formContainer = formContainer;
      this.sidebarContainer = sidebarContainer;
      // The step forms should already be part of the page, so only add them to the sidebar and the state.
      // Get all forms present in the page.
      document.querySelectorAll('.itemDisplay').forEach((form) => {
        const objectIndex = getObjectIndexFromId(form.id);
        this.registerStep(objectIndex, form, createStepEntry(objectIndex, form));
      });
      // Store element data, for later diffing.
      this.initialStepObjects = getStepIds();
      // Show first step.
      if (this.initialStepObjects.length > 0) {
        this.showStep(this.initialStepObjects[0]);
      }
    }
    async addStep(objectIndex) {
      if (!objectIndex) {
        objectIndex = getNextStepNumber();
      }
      const formElement = await createStepForm(objectIndex);
      this.registerStep(objectIndex, formElement, createStepEntry(objectIndex, formElement));
      this.showStep(objectIndex);
    };
    removeStep(objectIndex) {
      const currentStep = this.stepElements[objectIndex];
      if (!currentStep) {
        console.error("Tried to remove step with inexistent number:", currentStep);
        return;
      }

      if (currentStep.sidebarItem.classList.contains('active')) {
        if (currentStep.sidebarItem.previousElementSibling && currentStep.sidebarItem.previousElementSibling.classList.contains('item')) {
          // If deleting current step, show the previous step once this one is deleted.
          this.showStep(Number(currentStep.sidebarItem.previousElementSibling.dataset.id));
        } else if (currentStep.sidebarItem.nextElementSibling && currentStep.sidebarItem.nextElementSibling.classList.contains('item')) {
          this.showStep(Number(currentStep.sidebarItem.nextElementSibling.dataset.id));
        }
      }

      // Remove stuff from DOM.
      currentStep.form.remove();
      currentStep.sidebarItem.remove();
      delete this.stepElements[objectIndex];
    }

    /**
     * Update the `order` field, and the `addedObjects` and `deletedObjects` hidden inputs, which are needed by the
     * XWiki save function.
     */
    updateHiddenInputs() {
      // Update the order field for all steps, to ensure that the order that is displayed is also the one that is stored in the page.
      this.sidebarContainer.querySelectorAll('.item').forEach((childElement, index) => {
        const objectIndex = childElement.dataset.id;
        const orderInput = this.stepElements[objectIndex].form.querySelector(`[id="${getStepId(objectIndex)}_order"]`);
        orderInput.value = index;
      });
      // Update the ObjectPolicy fields.
      this.formContainer.querySelectorAll('input[data-guidedtour-managed="true"]').forEach((input) => input.remove());

      const currentStepObjects = getStepIds();
      const initialSet = new Set(this.initialStepObjects);
      const currentSet = new Set(currentStepObjects);
      const addedObjects = currentSet.difference(initialSet);
      const deletedObjects = initialSet.difference(currentSet);

      addedObjects.forEach((stepNumber) => {
        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = 'addedObjects';
        input.value = `${xclassName}_${stepNumber}`;
        input.dataset.guidedtourManaged = 'true';
        this.formContainer.appendChild(input);
      });

      deletedObjects.forEach((stepNumber) => {
        const input = document.createElement('input');
        input.type = 'hidden';
        input.name = 'deletedObjects';
        input.value = `${xclassName}_${stepNumber}`;
        input.dataset.guidedtourManaged = 'true';
        this.formContainer.appendChild(input);
      });
    }
    reset() {
      this.initialStepObjects = getStepIds();
    }
    showStep(objectId) {
      const selectedStep = this.stepElements[objectId];
      if (!selectedStep) {
        console.error("Couldn't find step with id ", objectId);
        return;
      }

      Object.values(this.stepElements).forEach((currentStep) => {
        currentStep.sidebarItem.classList.toggle('active', currentStep.number === selectedStep.number);
        currentStep.form.classList.toggle('hidden', currentStep.number !== selectedStep.number);
      });
    }
  }

  const xclassName = 'XWiki.GuidedTour.StepClass';
  const isEdit = xm.action === 'edit';
  const stepsListContainer = document.querySelector('.stepsListContainer');
  const sidebarContainer = stepsListContainer.querySelector('.sidebar .item-list');
  const formContainer = stepsListContainer.querySelector('.content');
  const sidebarItemTemplate = sidebarContainer.querySelector('#step-item-template');

  /**
   * Get the object numbers of all steps currently present on the page.
   * @returns A list of object numbers
   */
  function getStepIds() {
    return Array.from(sidebarContainer.querySelectorAll('.item')).map(item => Number(item.dataset.id));
  }
  /**
   * Turn step XObject number into string id, for use in matching the form elements associated with the step.
   * @param objectIndex the XObject number of the step you want to get
   * @returns 
   */
  function getStepId(objectIndex) {
    return `${xclassName}_${objectIndex}`;
  }

  /**
   * Get the number of the XObject from a string id.
   * @param stepId 
   * @returns 
   */
  function getObjectIndexFromId(stepId) {
    return stepId.substring(xclassName.length + 1);
  }

  /**
   * Fetch the StepSheet and insert it into the Step Content.
   * @param objectIndex the object index of the newly added step (not to be confused with the step order)
   */
  async function createStepForm(objectIndex) {
    const url = new XWiki.Document(new XWiki.DocumentReference(XWiki.currentWiki, ['GuidedTour', 'Code'], 'StepSheet')).getURL() + '?' + $.param({
      'document': XWiki.currentDocument.getDocumentReference().toString(),
      'objectIndex': objectIndex,
      'xpage': 'plain',
    });
    // TODO: Add translations.
    const notification = new XWiki.widgets.Notification('Creating step...', 'inprogress');
    const text = await fetch(url).then(response => response.text());
    // const newElement = new DOMParser().parseFromString(text);
    // FIXME: This isn't quite right. I should first parse the text, and then get what I need.
    formContainer.insertAdjacentHTML('beforeend', text);
    const form = formContainer.querySelector(`[id="${getStepId(objectIndex)}"]`);
    // Ensure any pickers/editors are properly initialized.
    $(document).trigger('xwiki:dom:updated', {
      elements: [form],
    });

    // TODO: Add translations.
    notification.replace(new XWiki.widgets.Notification('Done', 'done'));
    return form;
  };

  /**
   * Set up the step title to update as the content of a step is being edited.
   */
  function bindStepItemTitleUpdate(objectIndex, form, stepItem) {
    // const form = document.querySelector(`[id="XWiki.GuidedTour.StepClass_${objectIndex}"]`);
    // Update the step name in the UI when the description changes.
    const descriptionField = form.querySelector(`[id="${getStepId(objectIndex)}_content"]`);
    $(descriptionField).on('keyup change', () => {
      stepItem.querySelector(`.step-item-title`).textContent = getStepTitle(objectIndex, form);
    });
  }

  function getStepTitle(objectIndex, form) {
    const descriptionField = form.querySelector(`[id="${getStepId(objectIndex)}_content"]`);
    if (descriptionField.value && descriptionField.value.trim()) {
      // Edit mode.
      return descriptionField.value.trim();
    } else if (descriptionField.textContent && descriptionField.textContent.trim()) {
      // View mode.
      return descriptionField.textContent.trim();
    } else {
      const stepOrderIndex = 1 + Array.from(formContainer.querySelectorAll('.itemDisplay')).indexOf(form);
      return `Step #${stepOrderIndex}`;
    }
  }

  /**
   * Create the step entry in the sidebar.
   * @param objectIndex 
   * @returns 
   */
  function createStepEntry(objectIndex, form) {
    const item = document.importNode(sidebarItemTemplate.content, true).children[0];
    item.dataset.id = objectIndex;
    item.querySelector('.step-item-title').textContent = getStepTitle(objectIndex, form);
    item.addEventListener('click', () => stepManager.showStep(objectIndex));

    if (isEdit) {
      const deleteButton = item.querySelector('.step-item-delete');
      deleteButton.addEventListener('click', (event) => {
        event.stopPropagation();
        stepManager.removeStep(objectIndex);
      });
      // Update title 
      bindStepItemTitleUpdate(objectIndex, form, item);
    }

    return item;
  }

  /**
   * This is used only to compute the object number for the backend, and shouldn't be used to get the order of
   * the steps.
   * @returns 
   */
  function getNextStepNumber() {
    const usedNumbers = getStepIds();
    let nextNumber = 0;
    while (usedNumbers.includes(nextNumber)) {
      nextNumber++;
    }
    return nextNumber;
  }

  // Start work.
  // The sidebar is built as part of the GuidedTourStepSheetManager constructor.
  const stepManager = new GuidedTourStepSheetManager(formContainer, sidebarContainer);

  $(document).on('xwiki:actions:beforeSave', () => {
    stepManager.updateHiddenInputs();
  });

  $(document).on('xwiki:document:saved xwiki:actions:cancel', () => {
    // TODO: Is there anything else to do here?
    stepManager.reset();
  });

  if (xm.action === 'edit') {
    // Set up the addStepButton.
    const addStepButton = document.querySelector('#add-step-btn');
    if (addStepButton) {
      addStepButton.addEventListener('click', (event) => {
        event.preventDefault();
        stepManager.addStep();
      });
    }
    // Handle the order hidden input as part of the drag & drop operation, if the page is in edit mode.
    $('.sidebar .item-list').sortable({
      items: '.item',
      cursor: "grabbing",
      update: function () {
        $(sidebarContainer).find('.item').each(function (i) {
          // FIXME: Escape this for the jQuery css selector?
          const objectIndex = $(this).data('id');
          const form = stepManager.stepElements[objectIndex].form;
          $(form).find(`input[id="${getStepId(objectIndex)}_order"`).val(i);
        });
      }
    });
  }
});

:root{
  --sidebar-w: 260px;
  --bg: #f6f7fb;
  --card: #ffffff;
  --muted: #727272;
  --accent: #2563eb;
  --radius: 10px;
  --gap: 20px;
  font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
}

.stepsListContainer{
  display:flex;
  gap:var(--gap);
  align-items:flex-start;
  margin:0 auto;
  width:100%;
}

/* Sidebar */
.stepsListContainer .sidebar{
  width:var(--sidebar-w);
  border-radius:var(--radius);
  padding:16px;
  flex-shrink:0;
  border: solid var(--muted);
}

.stepsListContainer .sidebar-title{
  margin:0 0 12px 0;
  font-size:14px;
  color:var(--muted);
}

.stepsListContainer .item-list{
  list-style:none;
  padding:0;
  margin:0;
  display:flex;
  flex-direction:column;
  gap:8px;
}

.step-item-title {
  /*max-width: 60%;*/
  text-overflow: ellipsis;
  overflow: hidden;
  text-wrap: nowrap;
}

.stepsListContainer .item{
  padding:10px 12px;
  border-radius:8px;
  cursor:pointer;
  color:#0f172a;
  align-items:center;
  justify-content:space-between;
  transition:all .12s ease;
  border:1px solid transparent;
  overflow: hidden;
  /* TODO: Use theme background instead. */
  background: white;
  display: flex;
}

.stepsListContainer .item .step-item-delete {
  flex-shrink: 0;
}

.stepsListContainer .item:hover{
  transform:translateY(-2px);
  box-shadow:0 4px 10px rgba(16,24,40,0.06);
}

.stepsListContainer .item.active{
  background:color-mix(in srgb, rgb(37,99,235) 4%, white 96%);
  border-color:rgba(37,99,235,0.18);
  color:var(--accent);
  font-weight:600;
}

/* Content (form area) */
.container .content{
  flex:1;
  background:var(--card);
  padding:20px;
  border-radius:var(--radius);
  min-height:320px;
}

.container .content-title{
  margin:0 0 16px 0;
  font-size:18px;
}

.container .props-form{
  display:grid;
  grid-template-columns:repeat(2, minmax(0,1fr));
  gap:12px 20px;
  align-items:start;
}

.container .field{
  display:flex;
  flex-direction:column;
  gap:8px;
}

.container .field label{
  font-size:13px;
  color:var(--muted);
}

.field input[type="text"],
.field select,
.field textarea{
  padding:10px 12px;
  border-radius:8px;
  border:1px solid #e6e9ef;
  background:#fff;
  font-size:14px;
  outline:none;
  transition:border-color .12s ease, box-shadow .12s ease;
}

.field input[type="text"]:focus,
.field select:focus,
.field textarea:focus{
  border-color:rgba(37,99,235,0.6);
  box-shadow:0 4px 10px rgba(37,99,235,0.08);
}

.field input[type="checkbox"]{
  width:18px;
  height:18px;
  transform:translateY(4px);
}

/* Make description span full width */
.field textarea{
  resize:vertical;
  min-height:88px;
  grid-column:1 / -1;
}

/* Actions row spans full width */
.container .actions{
  grid-column:1 / -1;
  display:flex;
  gap:10px;
  justify-content:flex-start;
  margin-top:6px;
}
/* Responsive */
@media (max-width:880px){
  .container{flex-direction:column}
  .sidebar{width:100%}
  .props-form{grid-template-columns:1fr}
  .field textarea{grid-column:1/1}
  .actions{justify-content:stretch}
}
